#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
rag_metadata_system.py

A self-contained Retrieval-Augmented Generation (RAG) system that filters and
ranks documents using metadata in addition to relevance to the user query.

Design
------
* Index    - BM25 (Okapi) lexical index over document content.
* Filter   - declarative metadata filters ($eq/$in/$gte/$contains/$or/...).
* Rank     - BM25 relevance score, then metadata boost rules (value-based
             boosts and recency half-life boosts) adjust the final score.
* Generate - grounded extractive answer with citations, a confidence score,
             and a fillable prompt template for optional LLM integration.
* Observe  - local-only in-memory query log (no network calls) for
             post-retrieval observability.

The implementation is pure Python 3 standard library. It never contacts any
external server.
"""

import json
import math
import re
import time
from collections import Counter
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Sequence

TOKEN_RE = re.compile(r"[a-z0-9']+")
SENTENCE_RE = re.compile(r"(?<=[.!?])\s+")

DEFAULT_PROMPT_TEMPLATE = (
    "Use the following context to answer the question. If you cannot answer "
    'based on the context, say "I don\'t have enough information."\n\n'
    "Context:\n{context}\n\nQuestion: {question}\n\nAnswer:"
)


def tokenize(text: str) -> List[str]:
    """Lowercase alphanumeric tokenization."""
    return TOKEN_RE.findall(text.lower())


@dataclass
class Document:
    """A retrievable document with structured metadata."""

    id: str
    content: str
    metadata: Dict[str, Any] = field(default_factory=dict)


# --------------------------------------------------------------------------
# Metadata filtering
# --------------------------------------------------------------------------

def match_operator(op: str, actual: Any, expected: Any) -> bool:
    """Apply a single metadata comparison operator."""
    if op == "$eq":
        return actual == expected
    if op == "$ne":
        return actual != expected
    if op == "$in":
        return actual in expected
    if op == "$nin":
        return actual not in expected
    if op == "$gt":
        return isinstance(actual, (int, float)) and actual > expected
    if op == "$gte":
        return isinstance(actual, (int, float)) and actual >= expected
    if op == "$lt":
        return isinstance(actual, (int, float)) and actual < expected
    if op == "$lte":
        return isinstance(actual, (int, float)) and actual <= expected
    if op == "$exists":
        return (expected is True) == (actual is not None)
    if op == "$contains":
        return isinstance(actual, str) and expected in actual
    if op == "$regex":
        return re.search(expected, str(actual)) is not None
    raise ValueError(f"unknown metadata operator: {op}")


class MetadataFilter:
    """Declarative filters over document metadata.

    Examples:
        {"category": "api"}
        {"priority": {"$in": ["high", "critical"]}}
        {"timestamp": {"$gte": 1700000000}}
        {"$or": [{"category": "api"}, {"category": "billing"}]}
        {"title": {"$regex": "release"}}
    """

    def __init__(self, spec: Dict[str, Any]):
        self.spec = spec

    def matches(self, metadata: Dict[str, Any]) -> bool:
        return self._match_spec(self.spec, metadata)

    def _match_spec(self, spec: Any, metadata: Dict[str, Any]) -> bool:
        if isinstance(spec, list):  # implicit AND of clauses
            return all(self._match_spec(s, metadata) for s in spec)
        if not isinstance(spec, dict):
            raise TypeError("metadata filter spec must be a dict or list of dicts")

        if "$and" in spec and not all(self._match_spec(s, metadata) for s in spec["$and"]):
            return False
        if "$or" in spec and not any(self._match_spec(s, metadata) for s in spec["$or"]):
            return False
        if "$not" in spec and self._match_spec(spec["$not"], metadata):
            return False

        for field_name, cond in spec.items():
            if field_name.startswith("$"):
                continue  # logical operators handled above
            actual = metadata.get(field_name)
            if isinstance(cond, dict) and any(k.startswith("$") for k in cond):
                for op, expected in cond.items():
                    if not match_operator(op, actual, expected):
                        return False
            else:
                if actual != cond:
                    return False
        return True


# --------------------------------------------------------------------------
# BM25 relevance index
# --------------------------------------------------------------------------

class BM25:
    """In-memory BM25 (Okapi) index over document content."""

    def __init__(self, k1: float = 1.5, b: float = 0.75):
        self.k1 = k1
        self.b = b
        self.doc_tokens: Dict[str, List[str]] = {}
        self.doc_len: Dict[str, int] = {}
        self.doc_freq: Counter = Counter()
        self.avgdl: float = 0.0

    def add_document(self, doc_id: str, tokens: Sequence[str]) -> None:
        tokens = list(tokens)
        self.doc_tokens[doc_id] = tokens
        self.doc_len[doc_id] = len(tokens)
        for t in set(tokens):
            self.doc_freq[t] += 1
        self.avgdl = sum(self.doc_len.values()) / len(self.doc_tokens)

    def idf(self, term: str) -> float:
        n = self.doc_freq.get(term, 0)
        return math.log((len(self.doc_tokens) - n + 0.5) / (n + 0.5) + 1.0)

    def score(self, query_tokens: Sequence[str], doc_id: str) -> float:
        tokens = self.doc_tokens.get(doc_id)
        if not tokens:
            return 0.0
        dl = self.doc_len[doc_id]
        tf = Counter(tokens)
        total = 0.0
        for term in set(query_tokens):
            f = tf.get(term, 0)
            if f == 0:
                continue
            denom = f + self.k1 * (1.0 - self.b + self.b * dl / self.avgdl)
            total += self.idf(term) * f * (self.k1 + 1.0) / denom
        return total


# --------------------------------------------------------------------------
# Metadata ranking (boost rules)
# --------------------------------------------------------------------------

@dataclass
class BoostRule:
    """Add `weight` to the boost factor when a metadata field matches."""

    field: str
    weight: float
    operator: str = "$eq"
    value: Any = True
    description: str = ""

    def applies(self, metadata: Dict[str, Any]) -> bool:
        return match_operator(self.operator, metadata.get(self.field), self.value)


@dataclass
class RecencyBoostRule:
    """Decaying recency boost based on a numeric timestamp metadata field."""

    field: str = "timestamp"
    weight: float = 0.4
    half_life_days: float = 90.0
    description: str = ""

    def factor(self, metadata: Dict[str, Any], now: float) -> float:
        ts = metadata.get(self.field)
        if not isinstance(ts, (int, float)):
            return 0.0
        age_days = max(0.0, now - ts) / 86400.0
        return self.weight * (0.5 ** (age_days / self.half_life_days))


@dataclass
class ScoredDocument:
    document: Document
    score: float          # final score = base_score * boost_factor
    base_score: float     # pure BM25 relevance to the query
    boost_factor: float   # metadata-derived multiplier


# --------------------------------------------------------------------------
# Retriever: filter candidates, then rank by relevance + metadata
# --------------------------------------------------------------------------

class Retriever:
    def __init__(
        self,
        documents: Sequence[Document],
        boost_rules: Optional[Sequence[BoostRule]] = None,
        recency_rules: Optional[Sequence[RecencyBoostRule]] = None,
        k1: float = 1.5,
        b: float = 0.75,
    ):
        self.documents = {d.id: d for d in documents}
        self.index = BM25(k1=k1, b=b)
        for d in documents:
            self.index.add_document(d.id, tokenize(d.content))
        self.boost_rules = list(boost_rules or [])
        self.recency_rules = list(recency_rules or [])

    def filter_documents(self, metadata_filter: Any = None) -> List[Document]:
        docs = list(self.documents.values())
        if metadata_filter is None:
            return docs
        if isinstance(metadata_filter, dict):
            metadata_filter = MetadataFilter(metadata_filter)
        return [d for d in docs if metadata_filter.matches(d.metadata)]

    def retrieve(
        self,
        query: str,
        k: int = 5,
        metadata_filter: Any = None,
        boost_rules: Optional[Sequence[BoostRule]] = None,
        recency_rules: Optional[Sequence[RecencyBoostRule]] = None,
        now: Optional[float] = None,
    ) -> List[ScoredDocument]:
        """Filter by metadata, then rank by BM25 relevance * metadata boost."""
        query = (query or "").strip()
        if not query:
            return []
        q_tokens = tokenize(query)
        boost_rules = self.boost_rules if boost_rules is None else boost_rules
        recency_rules = self.recency_rules if recency_rules is None else recency_rules
        now = time.time() if now is None else now

        results: List[ScoredDocument] = []
        for doc in self.filter_documents(metadata_filter):
            base = self.index.score(q_tokens, doc.id)
            boost = 1.0
            for rule in boost_rules:
                if rule.applies(doc.metadata):
                    boost += rule.weight
            for rule in recency_rules:
                boost += rule.factor(doc.metadata, now)
            results.append(ScoredDocument(doc, base * boost, base, boost))
        results.sort(key=lambda r: (-r.score, r.document.id))
        return results[:k]


# --------------------------------------------------------------------------
# Answer generation (grounded, extractive fallback; LLM-ready prompt)
# --------------------------------------------------------------------------

def extractive_answer(query: str, scored_docs: Sequence[ScoredDocument]) -> str:
    """Pick the sentence with the best lexical overlap with the query."""
    q_terms = set(tokenize(query))
    best_sentence, best_score = "", -1.0
    for sd in scored_docs:
        for sentence in SENTENCE_RE.split(sd.document.content.strip()):
            s_terms = set(tokenize(sentence))
            if not s_terms:
                continue
            overlap = len(q_terms & s_terms)
            score = overlap / math.sqrt(len(s_terms))
            if score > best_score:
                best_score, best_sentence = score, sentence.strip()
    return best_sentence or scored_docs[0].document.content[:200]


class QueryLog:
    """Local-only, in-memory observability log of retrieval events."""

    def __init__(self) -> None:
        self.entries: List[Dict[str, Any]] = []

    def record(
        self,
        query: str,
        results: Sequence[ScoredDocument],
        metadata_filter: Any = None,
    ) -> None:
        self.entries.append(
            {
                "timestamp": time.time(),
                "query": query,
                "metadata_filter": metadata_filter,
                "top_ids": [r.document.id for r in results],
                "top_scores": [round(r.score, 4) for r in results],
            }
        )


class RAGSystem:
    def __init__(
        self,
        retriever: Retriever,
        prompt_template: str = DEFAULT_PROMPT_TEMPLATE,
        query_log: Optional[QueryLog] = None,
    ):
        self.retriever = retriever
        self.prompt_template = prompt_template
        self.query_log = query_log if query_log is not None else QueryLog()

    def retrieve(self, query: str, **kwargs) -> List[ScoredDocument]:
        return self.retriever.retrieve(query, **kwargs)

    def retrieve_logged(self, query: str, **kwargs) -> List[ScoredDocument]:
        results = self.retriever.retrieve(query, **kwargs)
        self.query_log.record(query, results, metadata_filter=kwargs.get("metadata_filter"))
        return results

    def format_prompt(self, query: str, context: str) -> str:
        return self.prompt_template.format(question=query, context=context)

    def generate_answer(
        self,
        query: str,
        k: int = 3,
        metadata_filter: Any = None,
        **kwargs,
    ) -> Dict[str, Any]:
        results = self.retrieve_logged(query, k=k, metadata_filter=metadata_filter, **kwargs)
        if not results:
            return {
                "query": query,
                "answer": "I don't have enough information.",
                "confidence": 0.0,
                "sources": [],
                "prompt": self.format_prompt(query, ""),
            }
        context = "\n".join(f"[{i}] {r.document.content}" for i, r in enumerate(results, start=1))
        answer = extractive_answer(query, results)
        confidence = round(min(1.0, results[0].score / (1.0 + results[0].score)), 4)
        sources = [
            {
                "id": r.document.id,
                "score": round(r.score, 4),
                "base_score": round(r.base_score, 4),
                "boost_factor": round(r.boost_factor, 4),
                "metadata": r.document.metadata,
            }
            for r in results
        ]
        return {
            "query": query,
            "answer": answer,
            "context": context,
            "confidence": confidence,
            "sources": sources,
            "prompt": self.format_prompt(query, context),
        }


# --------------------------------------------------------------------------
# Evaluation
# --------------------------------------------------------------------------

def evaluate_retrieval(
    retriever: Retriever,
    test_cases: Sequence[Dict[str, Any]],
    k: int = 3,
    now: Optional[float] = None,
) -> Dict[str, Any]:
    """Recall@k, MRR, and query-coverage@k over labeled test cases."""
    agg = {"recall_at_k": [], "mrr": [], "query_coverage_at_k": []}
    rows = []
    for case in test_cases:
        query = case["query"]
        relevant = set(case.get("relevant_ids", []))
        results = retriever.retrieve(query, k=k, now=now)
        retrieved_ids = [r.document.id for r in results]
        hit_ranks = [rank for rank, rid in enumerate(retrieved_ids, start=1) if rid in relevant]
        recall = len(hit_ranks) / len(relevant) if relevant else 0.0
        mrr = 1.0 / hit_ranks[0] if hit_ranks else 0.0
        q_terms = set(tokenize(query))
        covered = set()
        for r in results:
            covered |= set(tokenize(r.document.content))
        coverage = len(q_terms & covered) / len(q_terms) if q_terms else 0.0
        agg["recall_at_k"].append(recall)
        agg["mrr"].append(mrr)
        agg["query_coverage_at_k"].append(coverage)
        rows.append(
            {
                "query": query,
                "retrieved_ids": retrieved_ids,
                "recall_at_k": round(recall, 3),
                "mrr": round(mrr, 3),
                "query_coverage_at_k": round(coverage, 3),
            }
        )
    summary = {name: round(sum(v) / len(v), 3) for name, v in agg.items()}
    return {"summary": summary, "cases": rows}


